import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"Tool comparison","description":"","frontmatter":{},"headers":[],"relativePath":"COMPARISON.md","filePath":"COMPARISON.md"}'),n={name:"COMPARISON.md"};function s(r,e,l,d,h,c){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="tool-comparison" tabindex="-1">Tool comparison <a class="header-anchor" href="#tool-comparison" aria-label="Permalink to &quot;Tool comparison&quot;">​</a></h1><blockquote><p><a href="./COMPARISON">🇬🇧 English</a> • <a href="./COMPARISON.ja">🇯🇵 日本語</a></p></blockquote><p>This document is intended for users who want to compare kiwa with existing wallet E2E companion tools. The contents are organized based on kiwa&#39;s capabilities as of v0.1.0, that is, as of 2026-06, and the roles described in each official repository / docs. The conclusion first: kiwa is positioned for stable headless E2E operation using anvil.</p><h2 id="comparison-table" tabindex="-1">Comparison table <a class="header-anchor" href="#comparison-table" aria-label="Permalink to &quot;Comparison table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspect</th><th>Synpress</th><th>dappwright</th><th>wallet-mock</th><th>kiwa</th></tr></thead><tbody><tr><td>Primary target</td><td>E2E including real wallet integration</td><td>Real MetaMask / Coinbase Wallet extension automation</td><td>Headless wallet injection</td><td>dApp E2E assuming a local chain</td></tr><tr><td>Browser side</td><td>Playwright / Cypress + wallet extension integration</td><td>Playwright + extension download / unpack helpers</td><td>Inject a mock wallet into Playwright</td><td>Inject <code>window.ethereum</code> into Playwright</td></tr><tr><td>chain backend</td><td>Any backend paired with a real wallet</td><td>Any backend paired with a real wallet</td><td>Mock responses or arbitrary transport</td><td>Start anvil per test</td></tr><tr><td>Signing / transfers</td><td>Via the wallet UI</td><td>Via the wallet UI</td><td>Via mock or transport</td><td>Handled directly with anvil dev accounts</td></tr><tr><td>CI stability</td><td>Medium</td><td>Medium (depends on MetaMask version)</td><td>High</td><td>High</td></tr><tr><td>Best fit</td><td>Verifying wallet UX</td><td>Lightweight extension automation</td><td>Verifying provider replacement</td><td>Verifying connection flows on a local chain</td></tr></tbody></table><p>This is not a case where one tool is always superior. They target different things. In practice, it is best to choose based on whether your focus is wallet UI, provider mocking, or a local chain.</p><h2 id="positioning-of-kiwa" tabindex="-1">Positioning of kiwa <a class="header-anchor" href="#positioning-of-kiwa" aria-label="Permalink to &quot;Positioning of kiwa&quot;">​</a></h2><p>kiwa prioritizes the following three points.</p><ul><li>The ability to start anvil directly per test</li><li>The ability to run headlessly without bringing in a browser extension</li><li>The ability to reuse the minimum EIP-1193 core as a fixture</li></ul><p>In exchange, it does not cover checking wallet popup copy or reproducing extension UI interactions. This is also why the top of the README says to separate real MetaMask UI verification into another tool.</p><h2 id="selection-guide" tabindex="-1">Selection guide <a class="header-anchor" href="#selection-guide" aria-label="Permalink to &quot;Selection guide&quot;">​</a></h2><h3 id="when-to-choose-synpress" tabindex="-1">When to choose Synpress <a class="header-anchor" href="#when-to-choose-synpress" aria-label="Permalink to &quot;When to choose Synpress&quot;">​</a></h3><ul><li>You want to cover connection, approval, and rejection flows through a real wallet UI</li><li>You want to catch rendering issues on the browser extension side as well as in the dApp</li><li>You want to keep using a Playwright- or Cypress-based setup with a wallet extension</li></ul><p>Synpress is a strong option when you want to bring in integration with a real wallet implementation. On the other hand, because it adds browser setup and extension dependencies, it often becomes more than you need when the goal is just to run headless tests quickly.</p><h3 id="when-to-choose-dappwright" tabindex="-1">When to choose dappwright <a class="header-anchor" href="#when-to-choose-dappwright" aria-label="Permalink to &quot;When to choose dappwright&quot;">​</a></h3><ul><li>You want a lightweight Playwright helper that automates MetaMask or Coinbase Wallet extensions</li><li>You only need extension download / unpack / load helpers without the full Synpress stack</li><li>You are comfortable pinning a specific MetaMask version that dappwright is known to support</li></ul><p>dappwright sits between Synpress and wallet-mock in terms of scope. It bundles extension automation as a thin Playwright helper rather than as a full E2E framework, which keeps the surface area smaller than Synpress. On the other hand, real MetaMask extension automation as a whole has structural fragility with recent MetaMask versions (see the next section), so the same caveats around CI stability apply.</p><h3 id="when-to-choose-wallet-mock" tabindex="-1">When to choose wallet-mock <a class="header-anchor" href="#when-to-choose-wallet-mock" aria-label="Permalink to &quot;When to choose wallet-mock&quot;">​</a></h3><ul><li>You want to inject a provider headlessly</li><li>You want fine-grained control over mocked responses</li><li>You care more about verifying dApp-side branches than about connecting to a real chain</li></ul><p>wallet-mock is close in spirit in that it injects a wallet into Playwright, but it assumes the consumer will build anvil lifecycle management and local-chain isolation themselves. It is a good fit for tests where you want full freedom to swap transports.</p><h3 id="when-to-choose-kiwa" tabindex="-1">When to choose kiwa <a class="header-anchor" href="#when-to-choose-kiwa" aria-label="Permalink to &quot;When to choose kiwa&quot;">​</a></h3><ul><li>You want to run dApp E2E against a local chain backed by anvil that you set up yourself</li><li>The minimal provider surface is enough, and you do not need wallet UI</li><li>You want to call <code>window.ethereum</code> requests / events directly from the page</li><li>You want startup, injection, and teardown to stay contained within Playwright fixtures alone</li></ul><p>kiwa is the best fit for the use case of headlessly testing the dApp itself on a local chain. If you want to bundle the flow from <code>eth_requestAccounts</code> through <code>eth_sendTransaction</code> into one fixture, <code>examples/basic-connect</code> in this repository is the shortest path to get started.</p><h2 id="rules-of-thumb" tabindex="-1">Rules of thumb <a class="header-anchor" href="#rules-of-thumb" aria-label="Permalink to &quot;Rules of thumb&quot;">​</a></h2><ol><li>Choose Synpress or dappwright if wallet UI fidelity matters</li><li>Choose wallet-mock if provider replacement and mock control are the main goal</li><li>Choose kiwa if you want both local-chain dApp behavior and CI stability</li></ol><h2 id="why-kiwa-does-not-own-metamask-extension-automation" tabindex="-1">Why kiwa does not own MetaMask extension automation <a class="header-anchor" href="#why-kiwa-does-not-own-metamask-extension-automation" aria-label="Permalink to &quot;Why kiwa does not own MetaMask extension automation&quot;">​</a></h2><p>kiwa deliberately leaves real MetaMask extension automation to Synpress and dappwright rather than implementing it in-house. This is the result of running ten different automation approaches end-to-end during the PoC phase and finding a common structural blocker that one OSS library cannot route around.</p><p>The shared root cause across all ten attempts is that the MetaMask <code>chrome.sidePanel</code> API is undefined under automated browsers, the click handler falls through a <code>catch</code> branch, and the wallet-ready component keeps <code>disabled</code> true via its <code>H &amp;&amp; q</code> guard so the navigation dispatch never fires. We tried the README onboarding flow, longer waits, bypassing <code>manage-default-settings</code>, stripping <code>disabled</code> attributes, headful Chromium, downgrading to v13.17.0, full Synpress install, vendoring the MetaMask official e2e flow, vendoring dappwright, and writing the encrypted vault straight into <code>chrome.storage</code> — all ten ran into the same blocker.</p><p>The takeaway is not that any single library is broken, but that the structural blocker lives in MetaMask itself. A library that wants to fully automate the real MetaMask extension has to track upstream changes closely and accept brittleness against new MetaMask versions, which is a sustained maintenance cost. kiwa instead focuses on contract and UI logic testing on top of anvil and a minimal <code>window.ethereum</code> injection, and points users at Synpress or dappwright when they need to verify the real wallet UX.</p><p>Using more than one is also realistic. For example, using kiwa for everyday regression coverage and Synpress only for wallet UX checks before release is a perfectly reasonable split. The more a team wants to test the wallet layer and the dApp layer separately, the more this split pays off.</p><h2 id="cases-where-kiwa-is-not-a-good-fit" tabindex="-1">Cases where kiwa is not a good fit <a class="header-anchor" href="#cases-where-kiwa-is-not-a-good-fit" aria-label="Permalink to &quot;Cases where kiwa is not a good fit&quot;">​</a></h2><ul><li>You want to verify the exact copy or placement of buttons in an extension popup</li><li>You want to observe conflicts between multiple wallet extensions or differences between browser profiles</li><li>You want to fully mock the provider and decouple it from chain connectivity</li></ul><p>In this area, kiwa&#39;s design as a minimum provider centered on anvil becomes a constraint directly. If reproducing wallet UI is the main goal, Synpress is a better fit. If transport-swapping flexibility is the main goal, wallet-mock aligns better with the design intent.</p><h2 id="things-to-confirm-before-choosing-kiwa" tabindex="-1">Things to confirm before choosing kiwa <a class="header-anchor" href="#things-to-confirm-before-choosing-kiwa" aria-label="Permalink to &quot;Things to confirm before choosing kiwa&quot;">​</a></h2><ul><li>Whether you have an environment where anvil is available</li><li>Whether you can structure tests around a local anvil chain</li><li>Whether you can separate wallet extension UI checks into another layer</li><li>Whether you want to manage <code>viem</code> and Playwright on the host project side</li></ul><p>If these four points are acceptable, there is a good chance kiwa&#39;s design will fit well.</p><h2 id="ai-spec-driven-test-generation-comparison" tabindex="-1">AI / spec-driven test generation comparison <a class="header-anchor" href="#ai-spec-driven-test-generation-comparison" aria-label="Permalink to &quot;AI / spec-driven test generation comparison&quot;">​</a></h2><p>The sections above compare kiwa with other dApp E2E fixtures, but kiwa also includes Claude Code skills (<code>/kiwa-design</code>, <code>/kiwa-forge</code>, <code>/kiwa-hardhat</code>, <code>/kiwa-play</code>, <code>/kiwa-vitest</code>, <code>/kiwa-api</code>, <code>/kiwa-review</code>, <code>/kiwa-test</code>) that design and generate tests across four layers (contract / unit / integration / e2e) from a single specification. This section compares that side of kiwa.</p><table tabindex="0"><thead><tr><th>Aspect</th><th>hardhat-test-suite-generator</th><th>Foundry / Hardhat AI plugins (2026)</th><th>Claude Code spec-driven dev</th><th>kiwa skill chain</th></tr></thead><tbody><tr><td>Approach</td><td>Static template scaffold from contract ABI</td><td>LLM fuzz seed / invariant suggestion as plugin</td><td>Free-form spec → test → code iteration</td><td>11-viewpoint spec → 4-layer test code</td></tr><tr><td>Scope</td><td>Hardhat contract test only</td><td>Contract layer (fuzz + invariant) only</td><td>General-purpose, language-agnostic</td><td>Contract + dApp e2e + unit + integration</td></tr><tr><td>Spec format</td><td>None (ABI-driven)</td><td>None (heuristic)</td><td>Free-form markdown</td><td>Fixed 9-section / 9-column markdown</td></tr><tr><td>Layer coverage</td><td>1 (Hardhat)</td><td>1 (fuzz / invariant on Foundry or Hardhat)</td><td>Determined per project</td><td>4 (contract / unit / integration / e2e)</td></tr><tr><td>Review loop</td><td>None</td><td>None</td><td>Manual</td><td><code>/kiwa-review</code> checks 11 viewpoints + spec drift</td></tr><tr><td>Best fit</td><td>Boilerplate scaffold for Hardhat</td><td>Fuzz / invariant augmentation</td><td>General LLM-assisted dev</td><td>dApp project covering contract + e2e simultaneously</td></tr></tbody></table><h3 id="when-kiwa-s-skill-chain-shines" tabindex="-1">When kiwa&#39;s skill chain shines <a class="header-anchor" href="#when-kiwa-s-skill-chain-shines" aria-label="Permalink to &quot;When kiwa&#39;s skill chain shines&quot;">​</a></h3><ul><li>You want spec → test → review → coverage report flowing in one command (<code>/kiwa-test --example {name}</code>)</li><li>You want a single 9-column spec table to drive Foundry, Hardhat, Playwright, and Vitest in parallel</li><li>You want the 11 viewpoints (happy / failure / boundary / state-transition / authorization / input-validation / idempotency / concurrency / performance / security / regression) explicitly applied to a dApp test suite</li></ul><h3 id="when-other-tools-fit-better" tabindex="-1">When other tools fit better <a class="header-anchor" href="#when-other-tools-fit-better" aria-label="Permalink to &quot;When other tools fit better&quot;">​</a></h3><ul><li>You only need Hardhat contract test scaffolding → <code>hardhat-test-suite-generator</code> is lighter</li><li>You only need fuzz seed augmentation on an existing Foundry repo → Foundry AI plugins fit</li><li>You want a general LLM-assisted dev loop with no dApp specifics → use Claude Code spec-driven dev as-is</li></ul><h2 id="what-kiwa-uniquely-owns" tabindex="-1">What kiwa uniquely owns <a class="header-anchor" href="#what-kiwa-uniquely-owns" aria-label="Permalink to &quot;What kiwa uniquely owns&quot;">​</a></h2><p>After comparing both axes (dApp E2E fixture and spec-driven test generation), kiwa&#39;s unique surface is the <strong>4-layer chain in one entry point</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/kiwa-design (Layer 1)</span></span>
<span class="line"><span>  ├─ /kiwa-forge        → Foundry .t.sol</span></span>
<span class="line"><span>  ├─ /kiwa-hardhat      → Hardhat .test.ts</span></span>
<span class="line"><span>  ├─ /kiwa-play         → Playwright .spec.ts (uses @kiwa/dapp fixture)</span></span>
<span class="line"><span>  ├─ /kiwa-vitest       → Vitest .test.ts (unit)</span></span>
<span class="line"><span>  ├─ /kiwa-api          → Vitest + msw / supertest (integration)</span></span>
<span class="line"><span>  └─ /kiwa-review       → spec vs implementation drift + 11 viewpoint coverage</span></span></code></pre></div><p>No competitor in either axis covers all four layers (contract + unit + integration + e2e) from a single spec at the time of writing.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="https://github.com/Synthetixio/synpress" target="_blank" rel="noreferrer">Synpress repository</a></li><li><a href="https://github.com/TenKeyLabs/dappwright" target="_blank" rel="noreferrer">dappwright repository</a></li><li><a href="https://github.com/johanneskares/wallet-mock" target="_blank" rel="noreferrer">wallet-mock repository</a></li><li><a href="https://github.com/ahmedali8/hardhat-test-suite-generator" target="_blank" rel="noreferrer">hardhat-test-suite-generator</a></li><li><a href="https://www.augmentcode.com/guides/claude-code-spec-driven-development" target="_blank" rel="noreferrer">Claude Code spec-driven development</a></li><li><a href="https://book.getfoundry.sh/anvil/" target="_blank" rel="noreferrer">Foundry anvil docs</a></li><li><a href="./RPC">RPC.md</a></li><li><a href="./../README">README.md</a></li></ul>`,49)])])}const w=t(n,[["render",s]]);export{u as __pageData,w as default};
